# Website case studies built from the real project code (screens captured from the builds).
# build.py merges UPDATES into matching PROJECTS by slug and appends NEW projects.
# Screens live in assets/sc/<slug>/ (hero.webp, s1..s6.webp, mobile-1..3.webp).

def sc(slug, n):
    return f"assets/sc/{slug}/s{n}.webp"

def mob(slug):
    return [f"assets/sc/{slug}/mobile-{i}.webp" for i in (1, 2, 3)]


